import{_ as e,c as t,o,a2 as r}from"./chunks/framework.DdOM6S6U.js";const q=JSON.parse('{"title":"FileRequest","description":"","frontmatter":{"sidebarPos":4,"sidebarTitle":"FileRequest"},"headers":[],"relativePath":"system-reference/backend/http/request/file-request.md","filePath":"system-reference/backend/http/request/file-request.md","lastUpdated":1778363927000}'),d={name:"system-reference/backend/http/request/file-request.md"},a=r('<h1 id="filerequest" tabindex="-1">FileRequest <a class="header-anchor" href="#filerequest" aria-label="Permalink to &quot;FileRequest&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Requests/FileRequest.php</code><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Requests</code><strong>Extends</strong>: <a href="./request"><code>Request</code></a></p><p>Validates the payload posted to the file-library upload endpoint. The required fields depend on which backend is configured via <code>modularous.file_library.endpoint_type</code>.</p><h2 id="endpoint-specific-rules" tabindex="-1">Endpoint-specific rules <a class="header-anchor" href="#endpoint-specific-rules" aria-label="Permalink to &quot;Endpoint-specific rules&quot;">​</a></h2><p><code>rules()</code> reads <code>modularousConfig(&#39;file_library.endpoint_type&#39;)</code> and returns one of three rule sets:</p><table><thead><tr><th><code>endpoint_type</code></th><th>Required fields</th></tr></thead><tbody><tr><td><code>local</code></td><td><code>qqfilename</code>, <code>qqfile</code>, <code>qqtotalfilesize</code></td></tr><tr><td><code>azure</code></td><td><code>blob</code>, <code>name</code></td></tr><tr><td><code>s3</code> (default)</td><td><code>key</code>, <code>name</code></td></tr></tbody></table><p>The <code>s3</code> branch is used as the fallback for any unknown value.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Despite extending the model-aware <a href="./request"><code>Request</code></a> base, <code>FileRequest</code> overrides <code>rules()</code> completely — no translation expansion or <code>unique_table</code> hydration runs for this endpoint.</li><li>The per-backend field names mirror the client libraries they integrate with: FineUploader (<code>qq*</code> fields) for <code>local</code>, the Azure Blob SDK for <code>azure</code>, and S3 presigned uploads for <code>s3</code>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/system-reference/backend/http/controllers/file-library-controller"><code>FileLibraryController</code></a> — consumes this request</li><li><a href="/system-reference/backend/http/controllers/filepond-controller"><code>FilepondController</code></a> — related uploader endpoint</li><li><a href="/system-reference/backend/services/file-library/overview">Services · FileLibrary</a></li></ul>',11),s=[a];function l(i,c,n,u,h,p){return o(),t("div",null,s)}const b=e(d,[["render",l]]);export{q as __pageData,b as default};
